  </style>
</head>
<body>
  <main id="app"></main>
  <script>
    const app = document.querySelector('#app');
    const escapeHtml = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
    async function render() {
      const match = location.pathname.match(/^\/projects\/([^/]+)$/);
      if (match) {
        let project;
        try {
          const response = await fetch('/api/projects');
          project = (await response.json()).find(item => item.id === decodeURIComponent(match[1]));
        } catch {}
        if (!project) { history.replaceState({}, '', '/'); return render(); }
        const destinationProjects = (await (await fetch('/api/projects')).json()).filter(item => !item.archived && item.id !== project.id);
        app.innerHTML = `<button id="back" type="button">Projects</button><h1>${escapeHtml(project.name)}</h1>
          ${project.archived ? '<p>Archived project</p>' : ''}
          <form id="rename-form" novalidate>
            <label for="new-project-name">New project name</label>
            <input id="new-project-name" name="name" type="text" autocomplete="off" ${project.archived ? 'disabled' : ''}>
            <button type="submit" ${project.archived ? 'disabled' : ''}>Rename project</button>
            <p id="rename-alert" role="alert" hidden></p>
          </form>
          <form class="task-form" id="task-form" novalidate>
            <label for="task-title">Task title</label>
            <input id="task-title" name="title" type="text" autocomplete="off">
            <button type="submit" ${project.archived ? 'disabled' : ''}>Create task</button>
            <p id="alert" role="alert" hidden></p>
          </form>
          <div class="task-filter"><label for="default-task-priority">Default task priority</label>
            <select id="default-task-priority" ${project.archived ? 'disabled' : ''}><option ${project.defaultPriority === 'Low' ? 'selected' : ''}>Low</option><option ${project.defaultPriority === 'Normal' ? 'selected' : ''}>Normal</option><option ${project.defaultPriority === 'High' ? 'selected' : ''}>High</option></select>
          </div>
          <div class="task-filter"><label for="task-filter">Task filter</label>
            <select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select>
          </div>
          <div class="task-filter"><label for="priority-filter">Priority filter</label>
            <select id="priority-filter"><option>All</option><option>Low</option><option>Normal</option><option>High</option></select>
          </div>
          <form class="task-filter" id="due-range-form" novalidate>
            <label for="due-from">Due from</label><input id="due-from" type="text" placeholder="YYYY-MM-DD">
            <label for="due-through">Due through</label><input id="due-through" type="text" placeholder="YYYY-MM-DD">
            <button type="submit">Apply due range</button>
            <p id="due-range-alert" role="alert" hidden></p>
          </form>
          <form class="search-form" id="task-search-form">
            <label for="task-search">Task search</label><input id="task-search" type="text" autocomplete="off">
            <button type="submit">Search tasks</button>
          </form>
          <section id="tasks" aria-label="Tasks"></section>`;
        document.querySelector('#back').addEventListener('click', () => { history.pushState({}, '', '/'); render(); });
        document.querySelector('#rename-form').addEventListener('submit', async event => {
          event.preventDefault();
          const input = document.querySelector('#new-project-name');
          const alert = document.querySelector('#rename-alert');
          const name = input.value.trim();
          if (!name) { alert.textContent = 'Project name is required'; alert.hidden = false; input.focus(); return; }
          alert.hidden = true;
          const response = await fetch(`/api/projects/${encodeURIComponent(project.id)}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ name }) });
          if (response.ok) {
            // Keep the current filter controls and applied due range in place.
            // A project rename only changes the heading on this page.
            document.querySelector('h1').textContent = name;
          }
        });
        const tasks = document.querySelector('#tasks');
        const filter = document.querySelector('#task-filter');
        const priorityFilter = document.querySelector('#priority-filter');
        const defaultPriority = document.querySelector('#default-task-priority');
        let appliedTaskQuery = '';
        document.querySelector('#task-search-form').addEventListener('submit', event => {
          event.preventDefault();
          appliedTaskQuery = document.querySelector('#task-search').value.trim();
          refreshTasks();
        });
        const normalizeSearch = value => value.replace(/[ \t]+/g, ' ').replace(/[A-Z]/g, char => String.fromCharCode(char.charCodeAt(0) + 32));
        let appliedDueFrom = '', appliedDueThrough = '';
        const dueRangeAlert = document.querySelector('#due-range-alert');
        const isCalendarDate = value => {
          const match = value.match(/^(\d{4})-(\d{2})-(\d{2})$/);
          if (!match) return false;
          const year = Number(match[1]), month = Number(match[2]), day = Number(match[3]);
          const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
          const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
          return year >= 1 && month >= 1 && month <= 12 && day >= 1 && day <= days[month - 1];
        };
        document.querySelector('#due-range-form').addEventListener('submit', event => {
          event.preventDefault();
          const from = document.querySelector('#due-from').value.trim();
          const through = document.querySelector('#due-through').value.trim();
          if ((from && !isCalendarDate(from)) || (through && !isCalendarDate(through))) {
            dueRangeAlert.textContent = 'Due range must use valid YYYY-MM-DD dates'; dueRangeAlert.hidden = false; return;
          }
          if (from && through && from > through) {
            dueRangeAlert.textContent = 'Due from must not be after Due through'; dueRangeAlert.hidden = false; return;
          }
          appliedDueFrom = from; appliedDueThrough = through;
          dueRangeAlert.hidden = true;
          refreshTasks();
        });
        defaultPriority.addEventListener('change', async () => {
          await fetch(`/api/projects/${encodeURIComponent(project.id)}`, { method: 'PATCH', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ defaultPriority: defaultPriority.value }) });
        });
        async function refreshTasks() {
          const response = await fetch(`/api/projects/${encodeURIComponent(project.id)}/tasks`);
          const allTasks = await response.json();
          const visible = allTasks.filter(task =>
            (filter.value === 'All' || (filter.value === 'Open' ? !task.completed : !!task.completed)) &&
            (priorityFilter.value === 'All' || task.priority === priorityFilter.value) &&
            normalizeSearch(task.title).includes(normalizeSearch(appliedTaskQuery)) &&
            (!appliedDueFrom && !appliedDueThrough || !!task.dueDate) &&
            (!appliedDueFrom || task.dueDate >= appliedDueFrom) &&
